/* From Uiverse.io by Luciifer666 - Tags: loading, card, one-div */
.__UIV_SCOPE__ .one-div {
  width: 100px;
  height: 100px;
  margin: 100px auto;
  position: relative;
}

.__UIV_SCOPE__ .one-div::before, .__UIV_SCOPE__ .one-div::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 6px solid transparent;
}

.__UIV_SCOPE__ .one-div::before {
  border-top-color: #3468db;
  animation: spin 1.5s infinite linear;
}

.__UIV_SCOPE__ .one-div::after {
  border-top-color: #e67e22;
  animation: spin-reverse 1.5s infinite linear;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes spin-reverse {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(-360deg);
  }
}
